package io.github.ericmedvet.robotevo2d.main.noise;

import io.github.ericmedvet.jgea.core.InvertibleMapper;
import io.github.ericmedvet.jnb.core.NamedBuilder;
import io.github.ericmedvet.mrsim2d.core.agents.independentvoxel.NumIndependentVoxel;
import io.github.ericmedvet.mrsim2d.core.engine.Engine;
import io.github.ericmedvet.mrsim2d.core.tasks.locomotion.PrebuiltIndependentLocomotion;
import io.github.ericmedvet.mrsim2d.viewer.Drawer;
import java.io.*;
import java.util.*;
import java.util.function.Function;
import java.util.function.Supplier;
import java.util.stream.IntStream;

@SuppressWarnings("unchecked")
public class NoiseAnalyzer {
  final static NamedBuilder<Object> nb = NamedBuilder.fromDiscovery();

  private static Object base64Deserializer(String serialized) {
    byte[] bytes = Base64.getDecoder().decode(serialized);
    try (ObjectInputStream oois = new ObjectInputStream(new ByteArrayInputStream(bytes))) {
      return oois.readObject();
    } catch (IOException | ClassNotFoundException e) {
      throw new RuntimeException(e);
    }
  }

  public static void main(String[] args) {
    for (String task : List.of("locomotion", "holed-anch", "holed-anch-5")) {
      noiseAnalysis(task);
    }
  }

  public static void noiseAnalysis(String task) {
    final String taskBuilder = switch (task) {
      case "locomotion" ->
        "s.task.prebuiltIndependentLocomotion(duration = 30; initialXGap = 2.0; xGapRatio = 1.05; yGapRatio = 1.05; shape = s.a.vsr.shape.free(s = \"sss-sss\"))";
      case "holed-anch" ->
        "s.task.prebuiltIndependentLocomotion(terrain = s.terrain.holed(startW = 20; holeWs = [2.05]); terrainAttachableDistance = 0.0; initialXGap = 2.0; xGapRatio = 1.05; shape = s.a.vsr.shape.free(s = \"ssssssssss\"))";
      case "holed-anch-5" ->
        "s.task.prebuiltIndependentLocomotion(terrain = s.terrain.holed(startW = 8; holeWs = [2.05]); terrainAttachableDistance = 0.0; initialXGap = 2.0; xGapRatio = 1.05; shape = s.a.vsr.shape.free(s = \"sssss\"))";
      default -> "PORCODDIO";
    };
    List<Double> genotype = (List<Double>) base64Deserializer(switch (task) {
      case "locomotion" ->
        "";
      case "holed-anch" ->
        "";
      case "holed-anch-5" ->
        "";
      default -> "";
    });
    final long seed = switch (task) {
      case "locomotion" -> 13;
      case "holed-anch" -> 56;
      case "holed-anch-5" -> 51;
      default -> 0;
    };
    PrebuiltIndependentLocomotion pil = (PrebuiltIndependentLocomotion) nb.build(taskBuilder);
    final Supplier<NumIndependentVoxel> supplier = ((InvertibleMapper<List<Double>, Supplier<NumIndependentVoxel>>) nb
        .build(
            "er.m.noisedDsToNIV(sensors = [s.sensors.sin(); s.sensors.a(); s.sensors.ar(); s.sensors.rv(a = 0); s.sensors.rv(a = 90); s.sensors.d(a = 0; r = 5); s.sensors.d(a = 45; r = 5); s.sensors.d(a = 90; r = 5); s.sensors.d(a = 135; r = 5); s.sensors.d(a = 180; r = 5); s.sensors.d(a = 225; r = 5); s.sensors.d(a = 270; r = 5); s.sensors.d(a = 315; r = 5); s.sensors.sc(s = N); s.sensors.sc(s = E); s.sensors.sc(s = S); s.sensors.sc(s = W); s.sensors.sa(s = N); s.sensors.sa(s = E); s.sensors.sa(s = S); s.sensors.sa(s = W); s.sensors.c()]; function = ds.num.stepped(stepT = 0.2; inner = ds.num.mlp(nOfInnerLayers = 1; innerLayerRatio = 1)); bodySizeSigma = 0.5; sensorDistanceSigma = 0; sideContractionSigma = 0; parametersSigma = 0; randomGenerator = m.defaultRG(seed = %d))"
                .formatted(seed)
        )).mapperFor(null).apply(genotype);
    pil.run(
        supplier::get,
        ((Supplier<Engine>) nb.build("sim.engine()")).get(),
        new SingleFrames(
            ((Function<String, Drawer>) nb.build("s.drawer(info = false; parts = true; miniAgents = NONE)")).apply(""),
            "C:/Users/Francesco/Desktop/Università/Dottorato/Ricerca/Noise/Dimtest/Drawings/%s".formatted(task),
            IntStream.range(0, 6).mapToLong(i -> i).toArray(),
            800,
            600
        )
    );
  }
}